def two_sum(nums, target):
    seen = {}
    for i, x in enumerate(nums):
        if target - x in seen:
            return [seen[target - x], i]
        seen[x] = i
    return []

import java.util.*;

class Solution {
    public int[] twoSum(int[] nums, int target) {
        Map<Integer, Integer> seen = new HashMap<>();
        for (int i = 0; i < nums.length; i++) {
            if (seen.containsKey(target - nums[i])) return new int[]{seen.get(target - nums[i]), i};
            seen.put(nums[i], i);
        }
        return new int[0];
    }
}

def max_sub_array(nums):
    ans = cur = nums[0]
    for x in nums[1:]:
        cur = max(x, cur + x)
        ans = max(ans, cur)
    return ans

class Solution {
    public int maxSubArray(int[] nums) {
        int ans = nums[0], cur = nums[0];
        for (int i = 1; i < nums.length; i++) {
            cur = Math.max(nums[i], cur + nums[i]);
            ans = Math.max(ans, cur);
        }
        return ans;
    }
}

def max_area(height):
    left, right, ans = 0, len(height) - 1, 0
    while left < right:
        ans = max(ans, (right-left) * min(height[left], height[right]))
        if height[left] < height[right]:
            left += 1
        else:
            right -= 1
    return ans

class Solution {
    public int maxArea(int[] height) {
        int left = 0, right = height.length - 1, ans = 0;
        while (left < right) {
            ans = Math.max(ans, (right - left) * Math.min(height[left], height[right]));
            if (height[left] < height[right]) left++;
            else right--;
        }
        return ans;
    }
}

def trap(height):
    l, r = 0, len(height)-1
    lm = rm = water = 0
    while l < r:
        if height[l] <= height[r]:
            lm = max(lm, height[l]); water += lm-height[l]; l += 1
        else:
            rm = max(rm, height[r]); water += rm-height[r]; r -= 1
    return water

class Solution {
    public int trap(int[] h) {
        int l = 0, r = h.length - 1, lm = 0, rm = 0, ans = 0;
        while (l < r) {
            if (h[l] <= h[r]) { lm = Math.max(lm, h[l++]); ans += lm - h[l - 1]; }
            else { rm = Math.max(rm, h[r--]); ans += rm - h[r + 1]; }
        }
        return ans;
    }
}

def move_zeroes(nums):
    slow = 0
    for fast, x in enumerate(nums):
        if x != 0:
            nums[slow] = x; slow += 1
    for i in range(slow, len(nums)):
        nums[i] = 0

class Solution {
    public void moveZeroes(int[] nums) {
        int slow = 0;
        for (int x : nums) if (x != 0) nums[slow++] = x;
        while (slow < nums.length) nums[slow++] = 0;
    }
}

class Solution {
    public void merge(int[] a, int m, int[] b, int n) {
        int i = m - 1, j = n - 1, k = m + n - 1;
        while (i >= 0 && j >= 0) a[k--] = a[i] >= b[j] ? a[i--] : b[j--];
        while (j >= 0) a[k--] = b[j--];
    }
}

def remove_duplicates(nums):
    slow = 0
    for fast in range(1, len(nums)):
        if nums[fast] != nums[slow]:
            slow += 1; nums[slow] = nums[fast]
    return slow + 1

class Solution {
    public int removeDuplicates(int[] nums) {
        int slow = 0;
        for (int fast = 1; fast < nums.length; fast++)
            if (nums[fast] != nums[slow]) nums[++slow] = nums[fast];
        return slow + 1;
    }
}

import java.util.*;

class Solution {
    public List<List<Integer>> threeSum(int[] nums) {
        Arrays.sort(nums);
        List<List<Integer>> ans = new ArrayList<>();
        for (int i = 0; i < nums.length - 2; i++) {
            if (i > 0 && nums[i] == nums[i - 1]) continue;
            int l = i + 1, r = nums.length - 1;
            while (l < r) {
                int sum = nums[i] + nums[l] + nums[r];
                if (sum < 0) l++;
                else if (sum > 0) r--;
                else {
                    ans.add(new ArrayList<>(List.of(nums[i], nums[l++], nums[r--])));
                    while (l < r && nums[l] == nums[l - 1]) l++;
                    while (l < r && nums[r] == nums[r + 1]) r--;
                }
            }
        }
        return ans;
    }
}

class Solution {
    public int[] productExceptSelf(int[] nums) {
        int[] ans = new int[nums.length];
        ans[0] = 1;
        for (int i = 1; i < nums.length; i++) ans[i] = ans[i - 1] * nums[i - 1];
        for (int i = nums.length - 1, right = 1; i >= 0; i--) {
            ans[i] *= right;
            right *= nums[i];
        }
        return ans;
    }
}

def length_of_longest_substring(s):
    last={}; left=ans=0
    for right,ch in enumerate(s):
        if ch in last and last[ch]>=left: left=last[ch]+1
        last[ch]=right; ans=max(ans,right-left+1)
    return ans

import java.util.*;

class Solution {
    public int lengthOfLongestSubstring(String s) {
        Map<Character, Integer> last = new HashMap<>();
        int ans = 0;
        for (int left = 0, right = 0; right < s.length(); right++) {
            char c = s.charAt(right);
            if (last.containsKey(c) && last.get(c) >= left) left = last.get(c) + 1;
            last.put(c, right);
            ans = Math.max(ans, right - left + 1);
        }
        return ans;
    }
}

def is_valid(s):
    pairs={')':'(',']':'[','}':'{'}; st=[]
    for ch in s:
        if ch in '([{': st.append(ch)
        elif not st or st.pop()!=pairs[ch]: return False
    return not st

import java.util.*;

class Solution {
    public boolean isValid(String s) {
        Deque<Character> st = new ArrayDeque<>();
        for (char c : s.toCharArray()) {
            if (c == '(') st.push(')');
            else if (c == '[') st.push(']');
            else if (c == '{') st.push('}');
            else if (st.isEmpty() || st.pop() != c) return false;
        }
        return st.isEmpty();
    }
}

class MinStack:
    def __init__(self): self.st=[]; self.mn=[]
    def push(self,x):
        self.st.append(x); self.mn.append(min(x,self.mn[-1] if self.mn else x))
    def pop(self): self.st.pop(); self.mn.pop()
    def top(self): return self.st[-1]
    def getMin(self): return self.mn[-1]

import java.util.*;

class MinStack {
    private Deque<Long> values = new ArrayDeque<>();
    private Deque<Long> minimums = new ArrayDeque<>();

    public void push(int val) {
        values.push((long) val);
        minimums.push(Math.min((long) val, minimums.isEmpty() ? (long) val : minimums.peek()));
    }

    public void pop() { values.pop(); minimums.pop(); }
    public int top() { return values.peek().intValue(); }
    public int getMin() { return minimums.peek().intValue(); }
}

def next_greater(nums):
    ans=[-1]*len(nums); st=[]
    for i,x in enumerate(nums):
        while st and nums[st[-1]]<x: ans[st.pop()]=x
        st.append(i)
    return ans

import java.util.*;

class Solution {
    public int[] nextGreaterElements(int[] nums) {
        int[] ans = new int[nums.length];
        Arrays.fill(ans, -1);
        Deque<Integer> st = new ArrayDeque<>();
        for (int i = 0; i < nums.length; i++) {
            while (!st.isEmpty() && nums[st.peek()] < nums[i]) ans[st.pop()] = nums[i];
            st.push(i);
        }
        return ans;
    }
}

def daily_temperatures(T):
    ans=[0]*len(T); st=[]
    for i,x in enumerate(T):
        while st and T[st[-1]]<x: j=st.pop(); ans[j]=i-j
        st.append(i)
    return ans

import java.util.*;

class Solution {
    public int[] dailyTemperatures(int[] t) {
        int[] ans = new int[t.length];
        Deque<Integer> st = new ArrayDeque<>();
        for (int i = 0; i < t.length; i++) {
            while (!st.isEmpty() && t[st.peek()] < t[i]) ans[st.peek()] = i - st.pop();
            st.push(i);
        }
        return ans;
    }
}

def largest_rect(heights):
    hs=heights+[0]; st=[-1]; ans=0
    for i,h in enumerate(hs):
        while st[-1]!=-1 and hs[st[-1]]>=h:
            height=hs[st.pop()]
            ans=max(ans,height*(i-st[-1]-1))
        st.append(i)
    return ans

import java.util.*;

class Solution {
    public int largestRectangleArea(int[] hs) {
        Deque<Integer> st = new ArrayDeque<>();
        st.push(-1);
        int ans = 0;
        for (int i = 0; i <= hs.length; i++) {
            int h = i == hs.length ? 0 : hs[i];
            while (st.peek() != -1 && hs[st.peek()] >= h) {
                int height = hs[st.pop()];
                ans = Math.max(ans, height * (i - st.peek() - 1));
            }
            st.push(i);
        }
        return ans;
    }
}

def decode_string(s):
    cnt=[]; st=[]; cur=''; n=0
    for ch in s:
        if ch.isdigit(): n=n*10+int(ch)
        elif ch=='[': cnt.append(n); st.append(cur); n=0; cur=''
        elif ch==']': cur=st.pop()*cnt.pop()+cur
        else: cur+=ch
    return cur

import java.util.*;

class Solution {
    public String decodeString(String s) {
        Deque<Integer> counts = new ArrayDeque<>();
        Deque<StringBuilder> prefixes = new ArrayDeque<>();
        StringBuilder cur = new StringBuilder();
        for (int i = 0, n = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (Character.isDigit(c)) n = n * 10 + c - '0';
            else if (c == '[') { counts.push(n); prefixes.push(cur); cur = new StringBuilder(); n = 0; }
            else if (c == ']') {
                StringBuilder next = prefixes.pop();
                for (int k = counts.pop(); k > 0; k--) next.append(cur);
                cur = next;
            } else cur.append(c);
        }
        return cur.toString();
    }
}

from collections import deque
def max_window(nums,k):
    dq=deque(); ans=[]
    for i,x in enumerate(nums):
        while dq and nums[dq[-1]]<=x: dq.pop()
        dq.append(i)
        if dq[0]<=i-k: dq.popleft()
        if i>=k-1: ans.append(nums[dq[0]])
    return ans

import java.util.*;

class Solution {
    public int[] maxSlidingWindow(int[] nums, int k) {
        Deque<Integer> dq = new ArrayDeque<>();
        int[] ans = new int[nums.length - k + 1];
        for (int i = 0, j = 0; i < nums.length; i++) {
            while (!dq.isEmpty() && nums[dq.peekLast()] <= nums[i]) dq.pollLast();
            dq.addLast(i);
            if (dq.peekFirst() <= i - k) dq.pollFirst();
            if (i >= k - 1) ans[j++] = nums[dq.peekFirst()];
        }
        return ans;
    }
}

def eval_rpn(tokens):
    st=[]
    for x in tokens:
        if x in '+-*/':
            b=st.pop(); a=st.pop()
            if x=='+': st.append(a+b)
            elif x=='-': st.append(a-b)
            elif x=='*': st.append(a*b)
            else: st.append(int(a/b))
        else: st.append(int(x))
    return st[0]

import java.util.*;

class Solution {
    public int evalRPN(String[] tokens) {
        Deque<Integer> st = new ArrayDeque<>();
        for (String t : tokens) {
            switch (t) {
                case "+" -> st.push(st.pop() + st.pop());
                case "*" -> st.push(st.pop() * st.pop());
                case "-" -> { int b = st.pop(); st.push(st.pop() - b); }
                case "/" -> { int b = st.pop(); st.push(st.pop() / b); }
                default -> st.push(Integer.parseInt(t));
            }
        }
        return st.pop();
    }
}

