def subarray_sum(nums,k):
    seen=defaultdict(int); seen[0]=1; p=ans=0
    for x in nums:
        p+=x; ans+=seen[p-k]; seen[p]+=1
    return ans

import java.util.*;

class Solution {
    public int subarraySum(int[] nums, int k) {
        Map<Integer, Integer> seen = new HashMap<>();
        seen.put(0, 1);
        int prefix = 0, ans = 0;
        for (int x : nums) {
            prefix += x;
            ans += seen.getOrDefault(prefix - k, 0);
            seen.merge(prefix, 1, Integer::sum);
        }
        return ans;
    }
}

