def contains_nearby(nums,k):
    last={}
    for i,x in enumerate(nums):
        if x in last and i-last[x]<=k: return True
        last[x]=i
    return False

import java.util.*;

class Solution {
    public boolean containsNearbyDuplicate(int[] nums, int k) {
        Map<Integer, Integer> last = new HashMap<>();
        for (int i = 0; i < nums.length; i++) {
            if (last.containsKey(nums[i]) && i - last.get(nums[i]) <= k) return true;
            last.put(nums[i], i);
        }
        return false;
    }
}

from collections import Counter
def four_sum_count(A,B,C,D):
    ab=Counter(a+b for a in A for b in B)
    return sum(ab[-(c+d)] for c in C for d in D)

import java.util.*;

class Solution {
    public int fourSumCount(int[] a, int[] b, int[] c, int[] d) {
        Map<Integer, Integer> ab = new HashMap<>();
        for (int x : a) for (int y : b) ab.merge(x + y, 1, Integer::sum);
        int ans = 0;
        for (int x : c) for (int y : d) ans += ab.getOrDefault(-(x + y), 0);
        return ans;
    }
}

