class Solution {
    public Node copyRandomList(Node head) {
        if (head == null) return null;
        Map<Node, Node> copied = new HashMap<>();
        for (Node cur = head; cur != null; cur = cur.next) copied.put(cur, new Node(cur.val));
        for (Node cur = head; cur != null; cur = cur.next) {
            copied.get(cur).next = copied.get(cur.next);
            copied.get(cur).random = copied.get(cur.random);
        }
        return copied.get(head);
    }
}

class LRUCache:
    def __init__(self,cap):
        self.cap=cap; self.m={}; self.head=Node(); self.tail=Node(); self.head.next=self.tail; self.tail.prev=self.head
    def _remove(self,n): n.prev.next=n.next; n.next.prev=n.prev
    def _add(self,n): n.next=self.head.next; n.prev=self.head; self.head.next.prev=n; self.head.next=n
    def get(self,k):
        if k not in self.m: return -1
        n=self.m[k]; self._remove(n); self._add(n); return n.v
    def put(self,k,v):
        if k in self.m: n=self.m[k]; n.v=v; self._remove(n)
        else: n=Node(k,v); self.m[k]=n
        self._add(n)
        if len(self.m)>self.cap: old=self.tail.prev; self._remove(old); del self.m[old.k]

import java.util.*;

class LRUCache {
    private final int capacity;
    private final Map<Integer, Node> map = new HashMap<>();
    private final Node head = new Node(), tail = new Node();

    private static class Node {
        int key, value;
        Node prev, next;
    }

    public LRUCache(int capacity) {
        this.capacity = capacity;
        head.next = tail;
        tail.prev = head;
    }

    public int get(int key) {
        Node node = map.get(key);
        if (node == null) return -1;
        remove(node); addFirst(node);
        return node.value;
    }

    public void put(int key, int value) {
        Node node = map.get(key);
        if (node != null) { node.value = value; remove(node); }
        else {
            node = new Node(); node.key = key; map.put(key, node);
        }
        node.value = value; addFirst(node);
        if (map.size() > capacity) {
            Node old = tail.prev;
            remove(old); map.remove(old.key);
        }
    }

    private void remove(Node n) { n.prev.next = n.next; n.next.prev = n.prev; }
    private void addFirst(Node n) {
        n.next = head.next; n.prev = head;
        head.next.prev = n; head.next = n;
    }
}

