def search_rotated(nums,t):
    lo,hi=0,len(nums)-1
    while lo<=hi:
        mid=(lo+hi)//2
        if nums[mid]==t: return mid
        if nums[lo]<=nums[mid]:
            if nums[lo]<=t<nums[mid]: hi=mid-1
            else: lo=mid+1
