import threading
class BoundedQueue:
    def __init__(self,cap):
        self.cap=cap; self.items=[]; self.lock=threading.Lock(); self.not_full=threading.Condition(self.lock); self.not_empty=threading.Condition(self.lock)
    def put(self,x):
        with self.not_full:
            while len(self.items)==self.cap: self.not_full.wait()
            self.items.append(x); self.not_empty.notify()
    def get(self):
        with self.not_empty:
            while not self.items: self.not_empty.wait()
            x=self.items.pop(0); self.not_full.notify(); return x

